<form id="quiz-form">
  <div class="question" data-correct="A">
    <p>1. Quale metodo HTTP è idempotente?</p>
    <input type="radio" name="q1" value="A"> A) GET
    <input type="radio" name="q1" value="B"> B) POST
    <input type="radio" name="q1" value="C"> C) PATCH
    <input type="radio" name="q1" value="D"> D) DELETE
    <span class="feedback"></span>
  </div>
  <button type="submit">Calcola punteggio</button>
  <p>Punteggio: <span id="score">0</span>/5</p>
</form>

# JavaScript
<script>
const quizForm = document.getElementById('quiz-form');
const questions = quizForm.querySelectorAll('.question');

quizForm.addEventListener('submit', (e) => {
  e.preventDefault();
  let score = 0;
  questions.forEach(q => {
    const correct = q.dataset.correct;
    const selected = q.querySelector('input:checked');
    const feedback = q.querySelector('.feedback');
    if (selected && selected.value === correct) {
      score++;
      feedback.textContent = '✓ Corretto!';
      feedback.style.color = 'green';
    } else {
      feedback.textContent = `✗ Sbagliato! Corretta: ${correct}`;
      feedback.style.color = 'red';
    }
  });
  document.getElementById('score').textContent = score;
});
</script>
